#!/usr/bin/env python3
"""Exhaustive path-based validation fuzz: mutate every path of sample docs."""
import sys, json, copy, importlib.util
sys.path.insert(0, '/workspace/tmp')
import gen, gen2, gen3
from fuzz_invalid import run_main, run_ref, ERR, strict_loads

def paths(o, p=()):
    yield p
    if isinstance(o, dict):
        for k, v in o.items():
            yield from paths(v, p + (k,))
    elif isinstance(o, list):
        for i, v in enumerate(o):
            yield from paths(v, p + (i,))

def getp(doc, path):
    o = doc
    for p in path: o = o[p]
    return o

def setp(doc, path, val):
    o = doc
    for p in path[:-1]: o = o[p]
    o[path[-1]] = val

def delp(doc, path):
    o = doc
    for p in path[:-1]: o = o[p]
    del o[path[-1]]

VALUES = [True, False, 1.0, -1.5, "1", None, [], {}, [1], "", 2**80, -(2**80),
          10**13, -1, 0, 65537, 1e5]

def main():
    seeds = [int(x) for x in sys.argv[1:]] or [3, 8, 101, 202, 303]
    bad = 0
    tot = 0
    for seed in seeds:
        g = (gen, gen2, gen3)[seed % 3]
        base = g.gen(seed)
        allp = list(paths(base))
        for p in allp:
            for v in VALUES:
                for op in ('set', 'del', 'extra'):
                    doc = copy.deepcopy(base)
                    try:
                        if op == 'set':
                            setp(doc, p, v)
                        elif op == 'del':
                            delp(doc, p)
                        else:
                            node = getp(doc, p)
                            if not isinstance(node, dict): continue
                            node['extra_key_zz'] = 7
                    except Exception:
                        continue
                    text = json.dumps(doc)
                    tot += 1
                    a, b = run_main(text), run_ref(text)
                    if a != b:
                        bad += 1
                        print('MISMATCH', p, op, repr(v), 'seed', seed)
                        print('  got', json.dumps(a)[:200]); print('  exp', json.dumps(b)[:200])
                        if bad > 8: return
            # also array-length edits on list nodes
            node = getp(base, p)
            if isinstance(node, list):
                for op in ('pop', 'dup', 'empty'):
                    doc = copy.deepcopy(base)
                    n = getp(doc, p)
                    if op == 'pop' and n: n.pop()
                    elif op == 'dup': n.append(copy.deepcopy(n[0]) if n else 0)
                    elif op == 'empty': n.clear()
                    text = json.dumps(doc)
                    tot += 1
                    a, b = run_main(text), run_ref(text)
                    if a != b:
                        bad += 1
                        print('LIST MISMATCH', p, op, 'seed', seed)
                        print('  got', json.dumps(a)[:200]); print('  exp', json.dumps(b)[:200])
                        if bad > 8: return
        print('seed', seed, 'done, cumulative cases', tot, 'bad', bad)
    print('total', tot, 'mismatches', bad)

main()
